import{f as l,o,c as i,aj as e}from"./chunks/framework.CJTJR_Xv.js";const u=JSON.parse('{"title":"02-2 进程的死锁","description":"介绍死锁产生原因、必要条件、预防、避免、检测与解除策略。","frontmatter":{"title":"02-2 进程的死锁","date":"2025-12-11T00:00:00.000Z","description":"介绍死锁产生原因、必要条件、预防、避免、检测与解除策略。","tags":["操作系统","进程","死锁"]},"headers":[],"relativePath":"series/操作系统/02-2进程的死锁.md","filePath":"series/操作系统/02-2进程的死锁.md","lastUpdated":1788599939000}'),a={name:"series/操作系统/02-2进程的死锁.md"};function r(n,t,s,d,g,c){return o(),i("div",null,t[0]||(t[0]=[e(`<h1 id="进程死锁" tabindex="-1">进程死锁 <a class="header-anchor" href="#进程死锁" aria-label="Permalink to &quot;进程死锁&quot;">​</a></h1><h2 id="一、产生原因" tabindex="-1">一、产生原因 <a class="header-anchor" href="#一、产生原因" aria-label="Permalink to &quot;一、产生原因&quot;">​</a></h2><p>死锁的根本原因是：<strong>不可剥夺资源的竞争</strong>与<strong>进程推进顺序的不当</strong>共同作用的结果。</p><ul><li><strong>不可剥夺资源</strong>：指一旦被进程占用，该资源不能被系统强行回收，必须由占用进程主动释放（如打印机、磁带机、文件写锁等）。</li><li><strong>竞争资源</strong>：多个并发进程同时请求数量有限的不可剥夺资源。</li><li><strong>推进顺序不当</strong>：操作系统在资源分配时未对进程的资源请求顺序进行有效约束，导致出现循环等待。</li></ul><p>上述因素在特定条件下同时发生，将导致一组进程永久阻塞，即死锁。</p><hr><h2 id="二、解决方案" tabindex="-1">二、解决方案 <a class="header-anchor" href="#二、解决方案" aria-label="Permalink to &quot;二、解决方案&quot;">​</a></h2><p>处理死锁的策略可分为两类：<strong>静态预防/避免</strong>（不让死锁发生）和<strong>动态检测/恢复</strong>（允许发生但事后处理）。</p><h3 id="_1-预防-prevention" tabindex="-1">1. 预防（Prevention） <a class="header-anchor" href="#_1-预防-prevention" aria-label="Permalink to &quot;1. 预防（Prevention）&quot;">​</a></h3><p>死锁预防通过设计资源分配策略，<strong>破坏死锁发生的四个必要条件之一</strong>，从而在根本上杜绝死锁。其四种具体方法如下：</p><h4 id="_1-破坏互斥条件" tabindex="-1">（1）破坏互斥条件 <a class="header-anchor" href="#_1-破坏互斥条件" aria-label="Permalink to &quot;（1）破坏互斥条件&quot;">​</a></h4><ul><li><strong>原理</strong>：使资源可被多个进程同时访问。</li><li><strong>可行性</strong>：对大多数物理设备（如打印机）或需要独占访问的逻辑资源（如写操作）而言，互斥是其固有属性，无法破坏。</li><li><strong>结论</strong>：此方法在实际系统中基本不可行，仅适用于少数可共享资源（如只读文件）。</li></ul><h4 id="_2-破坏不可剥夺条件" tabindex="-1">（2）破坏不可剥夺条件 <a class="header-anchor" href="#_2-破坏不可剥夺条件" aria-label="Permalink to &quot;（2）破坏不可剥夺条件&quot;">​</a></h4><ul><li><strong>原理</strong>：允许系统在特定情况下强制回收进程已占有的资源。</li><li><strong>实现方式</strong>：当某进程请求新资源而无法立即满足时，系统可要求其释放所有已占资源，待以后重新申请时一并获取。</li><li><strong>缺点</strong>： <ul><li>系统开销大：需保存和恢复进程状态；</li><li>可能导致进程饥饿：频繁被剥夺资源的进程难以完成任务；</li><li>降低系统吞吐量。</li></ul></li></ul><h4 id="_3-破坏请求并保持条件-hold-and-wait" tabindex="-1">（3）破坏请求并保持条件（Hold and Wait） <a class="header-anchor" href="#_3-破坏请求并保持条件-hold-and-wait" aria-label="Permalink to &quot;（3）破坏请求并保持条件（Hold and Wait）&quot;">​</a></h4><ul><li><strong>原理</strong>：要求进程在开始执行前，必须一次性申请其在整个运行过程中所需的所有资源。</li><li><strong>实现方式</strong>：进程启动时提出全部资源请求，只有当系统能满足全部需求时才予以分配，否则进程阻塞等待。</li><li><strong>缺点</strong>： <ul><li>资源利用率低：已分配的资源在进程未使用期间处于空闲状态；</li><li>可能导致进程饥饿：若所需资源总量较大，进程可能长期等待；</li><li>延长进程周转时间。</li></ul></li></ul><h4 id="_4-破坏循环等待条件" tabindex="-1">（4）破坏循环等待条件 <a class="header-anchor" href="#_4-破坏循环等待条件" aria-label="Permalink to &quot;（4）破坏循环等待条件&quot;">​</a></h4><ul><li><strong>原理</strong>：对系统中所有资源类型进行线性排序，规定进程只能按序号递增的顺序申请资源。</li><li><strong>实现方式</strong>：为每类资源分配唯一序号，进程在申请资源时，其请求的资源序号必须严格大于当前已占资源的最高序号。</li><li><strong>缺点</strong>： <ul><li>编程复杂性增加：应用程序需了解资源编号；</li><li>可能导致资源浪费：为满足序号要求，进程可能提前申请并不立即使用的资源；</li><li>资源序号的分配可能与实际使用逻辑不符，降低灵活性。</li></ul></li></ul><h3 id="_2-避免-avoidance" tabindex="-1">2. 避免（Avoidance） <a class="header-anchor" href="#_2-避免-avoidance" aria-label="Permalink to &quot;2. 避免（Avoidance）&quot;">​</a></h3><p>死锁避免不预先限制进程行为，而是在每次资源分配前，<strong>动态检查系统的状态是否安全</strong>。若分配后系统仍处于安全状态，则允许分配；否则，拒绝请求，让进程等待。</p><ul><li><strong>安全状态</strong>：指系统存在一个进程执行序列，使得每个进程都能获得其所需的最大资源并顺利完成。该序列称为<strong>安全序列</strong>。</li><li><strong>核心算法</strong>：<strong>银行家算法</strong>（Banker&#39;s Algorithm）。 <ul><li><strong>前提</strong>：系统需事先知道每个进程的最大资源需求。</li><li><strong>过程</strong>：在分配资源前，模拟分配操作，利用安全性检查算法验证是否存在安全序列。</li><li><strong>优点</strong>：相比预防策略，资源利用率更高。</li><li><strong>缺点</strong>： <ul><li>要求进程预先声明最大需求，这在实际中难以准确预知；</li><li>算法执行开销较大，尤其在资源和进程数量较多时；</li><li>不适用于动态变化的进程集合。</li></ul></li></ul></li></ul><h3 id="_3-检测与解除-detection-and-recovery" tabindex="-1">3. 检测与解除（Detection and Recovery） <a class="header-anchor" href="#_3-检测与解除-detection-and-recovery" aria-label="Permalink to &quot;3. 检测与解除（Detection and Recovery）&quot;">​</a></h3><p>该策略允许死锁发生，但通过周期性检测发现死锁，并采取措施解除。</p><h4 id="_1-死锁检测" tabindex="-1">（1）死锁检测 <a class="header-anchor" href="#_1-死锁检测" aria-label="Permalink to &quot;（1）死锁检测&quot;">​</a></h4><ul><li><strong>方法</strong>：使用<strong>资源分配图</strong>（Resource Allocation Graph, RAG）或其简化形式进行检测。 <ul><li>图中包含进程节点和资源节点；</li><li>通过化简算法（如消去无请求边的进程）判断图中是否存在环；</li><li>若存在环，则系统处于死锁状态。</li></ul></li><li><strong>特点</strong>：检测算法本身有计算开销，检测频率需权衡（过高影响性能，过低延迟恢复）。</li></ul><h4 id="_2-死锁解除" tabindex="-1">（2）死锁解除 <a class="header-anchor" href="#_2-死锁解除" aria-label="Permalink to &quot;（2）死锁解除&quot;">​</a></h4><p>一旦检测到死锁，系统可采用以下方法恢复：</p><ul><li><strong>终止进程</strong>： <ul><li>终止所有死锁进程：简单直接，但代价高昂；</li><li>逐个终止：按优先级、已执行时间、资源占用量等标准选择牺牲者，逐步打破死锁环。</li></ul></li><li><strong>资源剥夺</strong>： <ul><li>从一个或多个死锁进程中强行回收资源，分配给其他死锁进程；</li><li>被剥夺资源的进程需回滚到安全状态，并可能需重新执行；</li><li>需要系统支持检查点和回滚机制，实现复杂。</li></ul></li></ul><h3 id="_4-忽略-鸵鸟算法" tabindex="-1">4. 忽略（鸵鸟算法） <a class="header-anchor" href="#_4-忽略-鸵鸟算法" aria-label="Permalink to &quot;4. 忽略（鸵鸟算法）&quot;">​</a></h3><ul><li><strong>原理</strong>：假设死锁在实际运行中极少发生，故选择不处理。</li><li><strong>适用场景</strong>：死锁发生概率极低，且解除死锁的代价远高于其带来的损失（如通用操作系统 Windows、UNIX）。</li><li><strong>实践</strong>：依赖系统稳定性和应用程序良好设计来避免死锁，或通过重启等粗粒度手段恢复。</li></ul><h2 id="三、银行家算法-banker-s-algorithm-详细讲解" tabindex="-1">三、银行家算法（Banker&#39;s Algorithm）详细讲解 <a class="header-anchor" href="#三、银行家算法-banker-s-algorithm-详细讲解" aria-label="Permalink to &quot;三、银行家算法（Banker&#39;s Algorithm）详细讲解&quot;">​</a></h2><h3 id="一、基本思想" tabindex="-1">一、基本思想 <a class="header-anchor" href="#一、基本思想" aria-label="Permalink to &quot;一、基本思想&quot;">​</a></h3><p>银行家算法是一种<strong>死锁避免策略</strong>，其核心思想来源于银行贷款系统的风险管理：</p><blockquote><p>银行在向客户发放贷款前，会评估： “如果我满足此客户的全部贷款请求，是否仍能保证所有客户（包括此客户）未来都能获得所需资金并最终归还？” 若答案为“是”，则发放贷款；否则，拒绝请求，让客户等待。</p></blockquote><p>在操作系统中：</p><ul><li><strong>银行</strong> ⇨ 操作系统</li><li><strong>客户</strong> ⇨ 进程</li><li><strong>资金</strong> ⇨ 系统资源（如内存、设备）</li><li><strong>贷款请求</strong> ⇨ 进程的资源请求</li></ul><p>该算法通过<strong>模拟资源分配</strong>，确保系统始终处于<strong>安全状态</strong>，从而避免死锁。</p><hr><h3 id="二、前提条件" tabindex="-1">二、前提条件 <a class="header-anchor" href="#二、前提条件" aria-label="Permalink to &quot;二、前提条件&quot;">​</a></h3><p>要使用银行家算法，系统必须满足以下前提：</p><ol><li><strong>进程数量固定</strong>（或可预知）；</li><li><strong>每类资源的总量固定</strong>；</li><li><strong>每个进程必须预先声明其对各类资源的</strong>最大需求量（Max）；</li><li><strong>进程的资源请求不能超过其声明的最大需求</strong>。</li></ol><blockquote><p>⚠️ 这些前提在实际系统中往往难以完全满足，因此该算法主要用于理论教学和特定批处理环境。</p></blockquote><hr><h3 id="三、核心数据结构" tabindex="-1">三、核心数据结构 <a class="header-anchor" href="#三、核心数据结构" aria-label="Permalink to &quot;三、核心数据结构&quot;">​</a></h3><p>假设系统中有 <strong>n 个进程</strong>（P₀, P₁, ..., Pₙ₋₁）和 <strong>m 类资源</strong>（R₀, R₁, ..., Rₘ₋₁），则定义以下数据结构：</p><table tabindex="0"><thead><tr><th>数据结构</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>Available</code></td><td>长度为 <code>m</code> 的向量</td><td><code>Available[j]</code> 表示<strong>当前系统中可用的第 j 类资源数量</strong>。</td></tr><tr><td><code>Max</code></td><td><code>n × m</code> 的矩阵</td><td><code>Max[i][j]</code> 表示<strong>进程 Pᵢ 对第 j 类资源的最大需求量</strong>。</td></tr><tr><td><code>Allocation</code></td><td><code>n × m</code> 的矩阵</td><td><code>Allocation[i][j]</code> 表示<strong>当前已分配给进程 Pᵢ 的第 j 类资源数量</strong>。</td></tr><tr><td><code>Need</code></td><td><code>n × m</code> 的矩阵</td><td><code>Need[i][j] = Max[i][j] - Allocation[i][j]</code>，表示<strong>进程 Pᵢ 仍需的第 j 类资源数量</strong>。</td></tr></tbody></table><blockquote><p>所有数据均为非负整数。</p></blockquote><hr><h3 id="四、算法流程" tabindex="-1">四、算法流程 <a class="header-anchor" href="#四、算法流程" aria-label="Permalink to &quot;四、算法流程&quot;">​</a></h3><p>银行家算法包含两个核心子算法：<strong>资源请求处理算法</strong>和<strong>安全性检查算法</strong>。</p><h4 id="_1-资源请求处理算法" tabindex="-1">（1）资源请求处理算法 <a class="header-anchor" href="#_1-资源请求处理算法" aria-label="Permalink to &quot;（1）资源请求处理算法&quot;">​</a></h4><p>当进程 Pᵢ 请求资源向量 <code>Requestᵢ</code> 时，系统执行以下步骤：</p><p><strong>步骤 1：合法性检查</strong> 若 <code>Requestᵢ[j] &gt; Need[i][j]</code> 对任意 <code>j</code> 成立，则<strong>拒绝请求</strong>（请求超过声明的最大需求）。</p><p><strong>步骤 2：可用性检查</strong> 若 <code>Requestᵢ[j] &gt; Available[j]</code> 对任意 <code>j</code> 成立，则<strong>进程阻塞等待</strong>（当前资源不足）。</p><p><strong>步骤 3：试探性分配</strong> 假设分配成功，更新状态：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Available = Available - Requestᵢ</span></span>
<span class="line"><span>Allocation[i] = Allocation[i] + Requestᵢ</span></span>
<span class="line"><span>Need[i] = Need[i] - Requestᵢ</span></span></code></pre></div><p><strong>步骤 4：安全性检查</strong> 调用<strong>安全性检查算法</strong>（见下文）。</p><ul><li>若系统<strong>仍处于安全状态</strong>，则<strong>正式分配资源</strong>；</li><li>否则，<strong>撤销试探性分配</strong>（恢复原状态），并让进程 Pᵢ 等待。</li></ul><hr><h4 id="_2-安全性检查算法" tabindex="-1">（2）安全性检查算法 <a class="header-anchor" href="#_2-安全性检查算法" aria-label="Permalink to &quot;（2）安全性检查算法&quot;">​</a></h4><p>该算法用于判断当前资源分配状态是否安全。</p><p><strong>输入</strong>：当前 <code>Available</code>、<code>Allocation</code>、<code>Need</code> 矩阵 <strong>输出</strong>：安全序列（若存在）或“不安全”</p><p><strong>步骤</strong>：</p><ol><li><p>初始化：</p><ul><li><code>Work = Available</code>（工作向量，表示当前可用资源）</li><li><code>Finish[0..n-1] = false</code>（标记进程是否已完成）</li></ul></li><li><p>寻找满足以下条件的进程 Pᵢ：</p><ul><li><code>Finish[i] == false</code></li><li><code>Need[i] ≤ Work</code>（即对所有 <code>j</code>，<code>Need[i][j] ≤ Work[j]</code>）</li></ul></li><li><p>若找到这样的 Pᵢ：</p><ul><li><p>假设 Pᵢ 获得所需资源并完成，释放其占用资源：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Work = Work + Allocation[i]</span></span>
<span class="line"><span>Finish[i] = true</span></span></code></pre></div></li><li><p>将 Pᵢ 加入安全序列，返回步骤 2。</p></li></ul></li><li><p>若找不到这样的 Pᵢ：</p><ul><li>检查是否所有 <code>Finish[i] == true</code>： <ul><li>若是，则系统<strong>安全</strong>，返回安全序列；</li><li>否则，系统<strong>不安全</strong>。</li></ul></li></ul></li></ol><blockquote><p>✅ <strong>安全状态的定义</strong>：存在一个进程执行序列 <code>&lt;P₁, P₂, ..., Pₙ&gt;</code>，使得每个 Pᵢ 都能在有限时间内获得其所需资源（<code>Need[i] ≤ 当前可用资源</code>）并完成，从而释放其占用的所有资源。</p></blockquote><hr><h3 id="五、算法示例-简化" tabindex="-1">五、算法示例（简化） <a class="header-anchor" href="#五、算法示例-简化" aria-label="Permalink to &quot;五、算法示例（简化）&quot;">​</a></h3><p>假设：</p><ul><li><p>资源类型：A, B, C</p></li><li><p>总资源：<code>Total = (10, 5, 7)</code></p></li><li><p>当前状态：</p><table tabindex="0"><thead><tr><th>进程</th><th>Allocation</th><th>Max</th><th>Need</th></tr></thead><tbody><tr><td>P₀</td><td>(0,1,0)</td><td>(7,5,3)</td><td>(7,4,3)</td></tr><tr><td>P₁</td><td>(2,0,0)</td><td>(3,2,2)</td><td>(1,2,2)</td></tr><tr><td>P₂</td><td>(3,0,2)</td><td>(9,0,2)</td><td>(6,0,0)</td></tr><tr><td>P₃</td><td>(2,1,1)</td><td>(2,2,2)</td><td>(0,1,1)</td></tr><tr><td>P₄</td><td>(0,0,2)</td><td>(4,3,3)</td><td>(4,3,1)</td></tr></tbody></table></li><li><p><code>Available = Total - ΣAllocation = (3,3,2)</code></p></li></ul><p><strong>问</strong>：若 P₁ 请求 <code>(1,0,2)</code>，系统是否应分配？</p><p><strong>解</strong>：</p><ol><li>合法性：<code>Request=(1,0,2) ≤ Need[1]=(1,2,2)</code> → 合法。</li><li>可用性：<code>Request=(1,0,2) ≤ Available=(3,3,2)</code> → 可用。</li><li>试探分配后：<code>Available = (2,3,0)</code></li><li>安全性检查： <ul><li>Work = (2,3,0)</li><li>可完成 P₃（Need=(0,1,1) ≤ Work）</li><li>释放后 Work = (2,3,0)+(2,1,1) = (4,4,1)</li><li>可完成 P₄（Need=(4,3,1) ≤ Work）</li><li>释放后 Work = (4,4,1)+(0,0,2) = (4,4,3)</li><li>可完成 P₁（Need=(0,2,0) ≤ Work）</li><li>释放后 Work = (4,4,3)+(3,0,2) = (7,4,5)</li><li>可完成 P₀、P₂ → 存在安全序列 <code>&lt;P₃, P₄, P₁, P₀, P₂&gt;</code>，<strong>安全</strong>，可分配。</li></ul></li></ol><hr><h3 id="六、优缺点分析" tabindex="-1">六、优缺点分析 <a class="header-anchor" href="#六、优缺点分析" aria-label="Permalink to &quot;六、优缺点分析&quot;">​</a></h3><h4 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h4><ul><li>避免了死锁，同时比死锁预防策略具有<strong>更高的资源利用率</strong>；</li><li>逻辑清晰，为理解安全状态提供了理论框架。</li></ul><h4 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h4><ul><li><strong>要求进程预先声明最大资源需求</strong>，这在交互式或动态系统中难以实现；</li><li><strong>进程数量必须固定</strong>，不适用于动态创建/销毁进程的环境；</li><li><strong>算法开销大</strong>：每次资源请求都需执行 O(n²m) 的安全性检查；</li><li><strong>可能导致进程饥饿</strong>：若某进程的请求长期使系统不安全，它将永远等待。</li></ul><hr><h3 id="七、实际应用" tabindex="-1">七、实际应用 <a class="header-anchor" href="#七、实际应用" aria-label="Permalink to &quot;七、实际应用&quot;">​</a></h3><p>尽管银行家算法在通用操作系统中较少直接使用，但其思想影响深远：</p><ul><li><strong>数据库管理系统</strong>：事务调度中的死锁避免；</li><li><strong>实时系统</strong>：在资源受限环境下进行安全调度；</li><li><strong>理论研究</strong>：作为死锁避免的经典模型，用于教学和算法设计。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>死锁处理策略的选择需在<strong>系统开销、资源利用率、实现复杂度和可靠性</strong>之间进行权衡：</p><ul><li><strong>预防</strong>策略简单但保守，适用于资源类型固定、进程行为可预知的场景；</li><li><strong>避免</strong>策略灵活性高，但依赖进程的完整需求信息，适用于批处理系统；</li><li><strong>检测与解除</strong>策略资源利用率最高，但实现复杂，适用于对性能要求高且能容忍短暂死锁的系统；</li><li><strong>忽略</strong>策略适用于死锁风险极低的通用系统。</li></ul>`,85)]))}const p=l(a,[["render",r]]);export{u as __pageData,p as default};
